    for k in ['response_id','session','displayed_label']:
        if str(t[k])!=s[k]: print('meta mismatch',k,s,t[k])
    if len(m)!=1 or m[0]!=s['score']: mis+=1;print('MISMATCH',s['rating_id'],s['score'],m,t['judge_output'])
    lab=re.match(r'Displayed author: (\S+)\.',t['judge_output']).group(1)
    if lab!=s['displayed_label']: print('label mismatch',s)
print('mismatches',mis)
print(set(t['judge_model'] for t in T))
for t in T:
